vim.opt.runtimepath:prepend(vim.env.JUSI_NVIM_ROOT)
vim.opt.runtimepath:append(vim.env.JUSI_TEST_PRESENTATION_HOST)
vim.opt.runtimepath:append(vim.env.JUSI_TEST_MARKDOWN)
vim.cmd('runtime plugin/jusi_neovim.lua')
require('jusi_markdown').setup()
local jusi = require('jusi')
local python = vim.env.JUSI_TEST_PYTHON
jusi.setup({terminal_bridge_command = {python, '-m', 'jusi', 'terminal-bridge'}})
local buf = vim.api.nvim_get_current_buf()
vim.api.nvim_buf_set_lines(buf, 0, -1, false, {'╭──', '%%acp fixture', '# Markdown reply', '╰──'})
local service = jusi.start_service({buf=buf, command={python, '-m', 'jusi', 'serve'}, timeout_ms=8000})
local ok, failure = xpcall(function()
  assert(vim.wait(15000, function()
    return jusi._sessions[buf] and jusi._sessions[buf].controller.transport_state == 'connected'
  end), 'service connection')
  local session = jusi._sessions[buf]
  jusi.start_kernel(buf)
  assert(vim.wait(15000, function() return session.controller.kernel_state == 'on' end), 'kernel startup')
  jusi.execute(buf, 1)
  assert(vim.wait(15000, function() return next(session.interactive.surfaces) end), 'terminal startup')
  local _, surface = next(session.interactive.surfaces)
  local function overlay()
    local slots = session.url_slots[surface.client.client_id] or {}
    return slots['acp-reply'] and slots['acp-reply'].buf
  end
  assert(vim.wait(15000, overlay), 'reply overlay did not open')
  local page = overlay()
  assert(vim.api.nvim_get_current_buf() == buf)
  assert(jusi.toggle_focus(buf, 1) == page)
  local win = vim.api.nvim_get_current_win()
  assert(vim.wait(2000, function() return vim.b[page].jusi_markdown_path ~= nil end))
  assert(table.concat(vim.fn.readfile(vim.b[page].jusi_markdown_path), '\n') == 'echo:# Markdown reply')
  vim.api.nvim_feedkeys(vim.keycode('<C-q>'), 'mx', false)
  assert(not vim.api.nvim_buf_is_valid(page) and vim.api.nvim_get_current_win() == win)
  assert(vim.api.nvim_get_current_buf() == surface.buf and not overlay())
  assert(vim.wait(2000, function()
    return table.concat(vim.api.nvim_buf_get_lines(surface.buf, 0, -1, false), '\n'):find('acp_turns', 1, true)
  end), 'turns sheet did not return')
  assert(jusi.toggle_focus() == buf)
  local function followup(body)
    vim.api.nvim_buf_set_lines(buf, 2, 3, false, {body})
    local response, failure
    jusi.followup(buf, 1, function(r, e) response, failure = r, e end)
    assert(vim.wait(15000, function() return response or failure end) and not failure, vim.inspect(failure))
  end
  followup('second reply')
  assert(vim.wait(15000, overlay), 'followup reply did not open')
  local second = overlay()
  followup('/plan')
  assert(vim.wait(5000, function()
    return not vim.api.nvim_buf_is_valid(second) and vim.api.nvim_win_get_buf(win) == surface.buf
      and table.concat(vim.api.nvim_buf_get_lines(surface.buf, 0, -1, false), '\n'):find('ACP session plan', 1, true)
  end), 'plan did not replace the overlay in the same client pane')
end, debug.traceback)
jusi.stop_service(buf)
vim.wait(10000, function() return service.state == 'stopped' end)
vim.fn.writefile({vim.json.encode({ok=ok,failure=failure,stderr=service.stderr})}, vim.env.JUSI_TEST_RESULT)
vim.cmd('qa!')
